import React, { useState } from 'react';
import logo from '../assets/Lucarative-Logo.png';
import { VLogo } from '../icons.jsx';

export default function Nav() {
  const [open, setOpen] = useState(false);

  const products = [
    { label: 'Lucrative Sales', href: '/loft' },
    { label: 'Lucrative Marketing', href: '/loft-marketing' },
    { label: 'Lucrative Analytics', href: '/stratum' },
    { label: 'Lucrative Quote', href: '/quotebase' },
    { label: 'Lucrative Governance', href: '/governance' },
  ];

  const links = [
    { label: 'Pricing', href: '/pricing' },
    { label: 'Partner', href: '/partners' },
    { label: 'Investors', href: '/investors' },
    { label: 'Contact Us', href: '/contact' },
  ];

  return (
    <header className="nav">
      <div className="container">

        {/* Logo */}
        <a href="#top" className="logo">
          <a href="#top" className="logo">LUCRAT<VLogo size={18} />E&nbsp;AI</a>
        </a>

        {/* Main Navigation */}
        <nav className="nav-links">

          {/* Products Dropdown */}
          <div
            className="nav-dropdown"
            onMouseEnter={() => setOpen(true)}
            onMouseLeave={() => setOpen(false)}
          >
            <button
              type="button"
              className="nav-dropdown-trigger"
              aria-expanded={open}
            >
              <span>Products</span>

              <span
                className={`dropdown-arrow ${open ? 'open' : ''}`}
              >
                ↓
              </span>
            </button>

            <div
              className={`nav-dropdown-menu ${
                open ? 'show' : ''
              }`}
            >
              {products.map((service) => (
                <a
                  key={service.label}
                  href={service.href}
                  className="nav-dropdown-item"
                  onClick={() => setOpen(false)}
                >
                  {service.label}
                </a>
              ))}
            </div>
          </div>

          {links.map((link) => (
            <a
              key={link.label}
              href={link.href}
            >
              {link.label}
            </a>
          ))}

        </nav>

        {/* Right Side */}
        <div className="nav-right">

          <a
            href="#signin"
            className="nav-signin"
          >
            Sign in
          </a>

          <a
            href="/pricing#configurator"
            className="btn btn-primary btn-sm"
          >
            Sign Up
          </a>

        </div>

      </div>
    </header>
  );
}